#!/usr/bin/env bash
# 053 -- testes da futura V1.0.280 (aparelhos so a partir das 14h da chegada) numa copia do codigo instalado (1.0.279). Nada instalado.
set -u
exec 2>&1
T=$(mktemp -d /tmp/v280.XXXX)
echo "" | base64 -d > $T/p.patch
echo "2e96ef599ef64300bca1bffb1d1f651f2c4523ddc21659eb5fecd120138a106f  $T/p.patch" | sha256sum -c --quiet || { echo "pacote corrompido"; exit 1; }
mkdir -p $T/repo && (cd /opt/PMS-Banana-AI && tar cf - --exclude=.venv --exclude=__pycache__ --exclude='*.pyc' --exclude=node_modules SISTEMA 2>/dev/null) | (cd $T/repo && tar xf - 2>/dev/null)
cd $T/repo && echo "copia: $(grep -oP 'VERSAO = "\K[^"]+' SISTEMA/api/app/versao.py)" && patch -p1 -s --no-backup-if-mismatch < $T/p.patch && echo "pacote 280 aplicado"
cd $T/repo/SISTEMA
P() { env -i PATH=/usr/local/bin:/usr/bin:/bin HOME=$T LANG=C.UTF-8 PYTHONDONTWRITEBYTECODE=1 timeout 600 /opt/PMS-Banana-AI/SISTEMA/.venv/bin/pytest -o addopts="-p no:cacheprovider" "$@" 2>&1; }
echo "== testes novos + luz"; P -q api/app/panel/tests/test_v1280_aparelhos_so_a_partir_das_14h.py api/app/luz/tests/test_luz.py | grep -vE '^\s*$' | tail -40 | cut -c1-240
echo "== suite inteira"; P -q --maxfail=60 api | grep -E '^(FAILED|ERROR)|[0-9]+ (passed|failed|error)' | tail -40 | cut -c1-220
rm -rf $T
